  let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9;[RUS,[[40,40.6],[135,41.6],[192,64]]].concat(Object.values(ISL)).forEach(a=>a.forEach(([lo,la])=>{const [x,y]=pr(lo,la);x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}));
  const W0=340,pad=6,sc=(W0-2*pad)/(x1-x0),H0=Math.round((y1-y0)*sc+2*pad);
  const P=(lo,la)=>{const [x,y]=pr(lo,la);return [pad+(x-x0)*sc,pad+(y-y0)*sc];};
  const box=(lo0,la0,lo1,la1)=>{let a=1e9,b=-1e9,c=1e9,d=-1e9;for(let i=0;i<=8;i++)for(let j=0;j<=8;j++){const [x,y]=P(lo0+(lo1-lo0)*i/8,la0+(la1-la0)*j/8);a=Math.min(a,x);b=Math.max(b,x);c=Math.min(c,y);d=Math.max(d,y);}return [a,c,b-a,d-c];};
