// L9 ★
G(9,()=>CH('★ Как найти температуру на вершине, если известны давление у подножия и на вершине?','по разности давлений найти высоту (1 мм рт. ст. — 10,5 м), затем понижение температуры (6 °C на 1 км)',['вычесть разность давлений из температуры', 'умножить давление на 6', 'температура с высотой не меняется'],{hint:'Вспомни правило из теории ★.',short:'по разности давлений найти высоту (1 мм рт. ст. — 10,5 м), затем понижение температуры (6 °C на 1 км)',explain:'Цепочка: Δp → высота = Δp · 10,5 м → понижение = высота (км) · 6 °C → температура вершины = t подножия − понижение.',explain2:'Пример: 760 → 700 мм рт. ст.: 60 · 10,5 = 630 м → 0,63 · 6 ≈ 3,8 °C холоднее.'}),{star:true,rule:true});

G(9,()=>{const p0=760,dh=pick([630,840,1050,1260]),t0=pick([20,22,24,25]);const p=p0-dh/10.5;const t=rnd(t0-6*dh/1000,1);
 return NUM(t,{q:`★ Альпинисты у подножия: давление ${p0} мм рт. ст., температура ${fmtT(t0)} °C. На перевале барометр показал ${p} мм рт. ст. Какая температура на перевале? (1 мм рт. ст. на 10,5 м; −6 °C на 1 км.) Ответ в °C, до десятых.`,hint:'Сначала по давлению найди высоту, потом температуру.',short:`h = (${p0} − ${p}) · 10,5 = ${dh} м; t = ${t0} − ${N(dh/1000)} · 6 = ${N(t)} °C.`,
 explain:`1) Перепад давления: ${p0} − ${p} = ${dh/10.5} мм → высота ${dh/10.5} · 10,5 = ${dh} м. 2) Понижение температуры: ${N(dh/1000)} км · 6 = ${N(6*dh/1000)} °C. 3) ${t0} − ${N(6*dh/1000)} = <b>${N(t)} °C</b>.`,explain2:'Это «цепочка» из двух правил — любимый приём олимпиад.'});},{star:true});
G(9,()=>{const h=pick([33.5,40.5,47.5,52.5,57.5,60.5]);const phi=rnd(90-h+23.5,1);
 return NUM(phi,{q:`★ 22 июня полуденное Солнце в пункте стояло на высоте ${N(h)}°. На какой широте (с. ш.) находится пункт? Наклон оси — 23,5°.`,hint:'h = 90 − φ + 23,5 → φ = 113,5 − h.',short:`φ = 90 + 23,5 − ${N(h)} = ${N(phi)}°.`,
 explain:`${M('h = 90° − φ + 23,5°')} → ${M(`φ = 113,5° − ${N(h)}° = ${N(phi)}°`)} с. ш.`,explain2:`Проверка: 90 − ${N(phi)} + 23,5 = ${N(rnd(113.5-phi,1))}° ✅.`});},{star:true});
G(9,()=>{const phi=pick([56,60,64,70]);const hs=90-phi+23.5,hw=90-phi-23.5;const d=rnd(hs-Math.max(hw,0),1);
 return NUM(47,{q:`★ На сколько градусов полуденная высота Солнца 22 июня больше, чем 22 декабря, на широте ${phi}° с. ш. (если в декабре Солнце восходит)? Считай по формулам, даже если декабрьская высота получится отрицательной.`,hint:'Вычти формулы: (90 − φ + 23,5) − (90 − φ − 23,5).',short:'2 · 23,5 = 47° на любой широте.',
 explain:`Летом ${M(`h = 90 − ${phi} + 23,5 = ${N(hs)}°`)}, зимой ${M(`h = 90 − ${phi} − 23,5 = ${N(hw)}°`)}. Разность: ${N(hs)} − (${N(hw)}) = <b>47°</b>. Широта сокращается — ответ одинаков для всех мест вне тропиков!`,explain2:'Это удвоенный наклон земной оси: 2 · 23,5° = 47°. Олимпиадная «ловушка» — начать считать для конкретной широты, хотя ответ общий.'});},{star:true});
G(9,()=>{const O=pick([400,500,600]),I=pick([700,800,900,1000]);const need=I-O;
 return NUM(need,{q:`★ В степи осадков ${O} мм в год, испаряемость ${I} мм. Сколько мм воды в год нужно добавить орошением, чтобы коэффициент увлажнения стал равен 1?`,hint:'K = (О + x) : И = 1.',short:`x = ${I} − ${O} = ${need} мм.`,
 explain:`Сейчас K = ${O} : ${I} ≈ ${N(rnd(O/I,2))}. Нужно ${M(`(${O} + x) : ${I} = 1`)} → ${M(`x = ${I} − ${O} = ${need} мм`)}.`,explain2:`${need} мм — это ${need} литров на каждый квадратный метр поля за год! Вот почему орошение — дорогое удовольствие.`});},{star:true});
G(9,()=>{const c=pick(Object.keys(CLIM));const d=CLIM[c];const A=Math.max(...d.T)-Math.min(...d.T);
 return NUM(A,{q:`★ По климатограмме определи годовую амплитуду температуры (°C).`,pic:climSVG(c,{wd:320}),hint:'Найди самую высокую и самую низкую точки красной линии.',short:`${fmtT(Math.max(...d.T))} − (${fmtT(Math.min(...d.T))}) = ${A}.`,
 explain:`Самый тёплый месяц: ${fmtT(Math.max(...d.T))} °C, самый холодный: ${fmtT(Math.min(...d.T))} °C. Амплитуда: ${Math.max(...d.T)} − (${N(Math.min(...d.T))}) = <b>${A} °C</b>. Тип климата — ${d.t}.`,explain2:'Читай шкалу слева (красные числа). Точки на линии — средние температуры месяцев.'});},{star:true});
/* ---------- interactive theory ---------- */
function onTheory(root){
  const s=root.querySelector('#w-sun');
  if(s){let dec=0;s.innerHTML=`<b>Высота Солнца: выбери широту и день</b><div id="sb" style="display:flex;gap:6px;flex-wrap:wrap;margin:6px 0"><button class="btn ghost" data-d="23.5">22 июня</button><button class="btn" data-d="0">Равноденствие</button><button class="btn ghost" data-d="-23.5">22 декабря</button></div>
    <label>Широта φ = <output id="so"></output><input type="range" id="sP" min="0" max="90" step="1" value="56"></label><div id="sp" class="fig"></div><div id="st" style="text-align:center;line-height:1.6"></div>`;
    const PL0=[[44,'Сочи'],[56,'Москва'],[60,'Санкт-Петербург'],[62,'Якутск'],[69,'Мурманск'],[78,'мыс Челюскин']];
    const u=()=>{const phi=+s.querySelector('#sP').value;s.querySelector('#so').textContent=phi+'° с. ш.';const h=90-Math.abs(phi-dec);const near=PL0.find(p=>Math.abs(p[0]-phi)<=1);
      s.querySelector('#sp').innerHTML=sunSVG(phi,dec);s.querySelector('#st').innerHTML=`h = 90° − ${phi}° ${dec>0?'+ 23,5°':dec<0?'− 23,5°':''} = <span class="out">${N(rnd(h,1))}°</span>${near?` <span class="small">(≈ ${near[1]})</span>`:''}<br><span class="small">${h<=0?'Полярная ночь: Солнце весь день под горизонтом.':dec>0&&phi>=66.5?'Полярный день: Солнце не заходит.':h>=89.5?'Солнце в зените!':''}</span>`;
      s.querySelectorAll('#sb button').forEach(b=>b.className='btn'+(+b.dataset.d===dec?'':' ghost'));};
    s.querySelector('#sb').addEventListener('click',e=>{const b=e.target.closest('[data-d]');if(b){dec=+b.dataset.d;u();}});s.querySelector('#sP').oninput=u;u();}
  const c=root.querySelector('#w-cyc');
  if(c){let anti=false;c.innerHTML=`<b>Циклон или антициклон?</b><div id="cb" style="display:flex;gap:6px;margin:6px 0"><button class="btn" data-a="0">Циклон</button><button class="btn ghost" data-a="1">Антициклон</button></div><div id="cp" class="fig"></div>`;
    const u=()=>{c.querySelector('#cp').innerHTML=cycSVG(anti);c.querySelectorAll('#cb button').forEach(b=>b.className='btn'+((b.dataset.a==='1')===anti?'':' ghost'));};
    c.querySelector('#cb').addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(b){anti=b.dataset.a==='1';u();}});u();}
  const k=root.querySelector('#w-clim');
  if(k){let cur='Москва';k.innerHTML=`<b>Климатограммы: выбери пункт</b><div id="kb" style="display:flex;gap:6px;flex-wrap:wrap;margin:6px 0">${Object.keys(CLIM).map(n=>`<button class="btn ghost" data-n="${n}" style="padding:5px 10px;font-size:14px">${n}</button>`).join('')}</div><div id="kp" class="fig"></div><div id="kt" style="line-height:1.6"></div>`;
    const u=()=>{const d=CLIM[cur];const A=Math.max(...d.T)-Math.min(...d.T);k.querySelector('#kp').innerHTML=climSVG(cur,{wd:420});k.querySelector('#kt').innerHTML=`Тип: <span class="out">${d.t}</span>. Январь ${fmtT(d.T[0])} °C, июль ${fmtT(d.T[6])} °C, амплитуда ${A} °C, осадков ${d.P.reduce((a,b)=>a+b,0)} мм.<br><span class="small">${CDESC[d.t]}</span>`;k.querySelectorAll('#kb button').forEach(b=>b.className='btn'+(b.dataset.n===cur?'':' ghost'));};
    k.querySelector('#kb').addEventListener('click',e=>{const b=e.target.closest('[data-n]');if(b){cur=b.dataset.n;u();}});u();}
  const iso=root.querySelector('#w-iso');
  if(iso){let mon=0;iso.innerHTML=`<b>Январь или июль? Средние температуры городов</b><div id="ib" style="display:flex;gap:6px;margin:6px 0"><button class="btn" data-m="0">Январь</button><button class="btn ghost" data-m="1">Июль</button></div><div id="ip" class="fig"></div><div id="it" class="small" style="text-align:center"></div>`;
    const col=t=>t<=-30?'var(--accent-ink)':t<=-15?'var(--accent)':t<0?'var(--ok)':t<15?'var(--hl)':'var(--bad)';
    const u=()=>{iso.querySelector('#ip').innerHTML=mapSVG({pad:true,wd:560,fillO:0.12,layer:(P,k)=>Object.keys(JJ).filter(c=>GEO.PT[c]).map(c=>{const [x,y]=P(...GEO.PT[c]);const t=JJ[c][mon];return CI(x,y,9,{f:col(t),fo:0.85,s:'var(--card)'})+`<text x="${r2(x)}" y="${r2(y+3)}" text-anchor="middle" font-size="7.5" font-weight="700" fill="var(--ink)">${fmtT(t)}</text>`;}).join('')});
      iso.querySelector('#it').innerHTML=mon?'Июль: температура растёт с севера на юг — изотермы почти вдоль параллелей.':'Январь: холоднее к востоку; в Якутии — полюс холода. Изотермы в европейской части почти вдоль меридианов.';
      iso.querySelectorAll('#ib button').forEach(b=>b.className='btn'+(+b.dataset.m===mon?'':' ghost'));};
    iso.querySelector('#ib').addEventListener('click',e=>{const b=e.target.closest('[data-m]');if(b){mon=+b.dataset.m;u();}});u();}
}
